describe('Permissions Error - Edit Another User\'s Content', () => {
  const baseUrl = Cypress.env('BASE_URL') || 'http://localhost:3000';
  const testUser1 = {
    email: 'user1@example.com',
    password: 'TestPassword123!',
    id: 'user-1'
  };
  const testUser2 = {
    email: 'user2@example.com',
    password: 'TestPassword456!',
    id: 'user-2'
  };

  beforeEach(() => {
    cy.visit(`${baseUrl}/login`);
    cy.clearCookies();
    cy.clearLocalStorage();
  });

  it('should display permissions error when attempting to edit another user\'s content', () => {
    // Login as user1
    cy.get('input[name="email"]').type(testUser1.email);
    cy.get('input[name="password"]').type(testUser1.password);
    cy.get('button[type="submit"]').click();
    cy.url().should('include', '/dashboard');
    cy.get('[data-testid="user-greeting"]').should('contain', testUser1.email);

    // Navigate to another user's content
    cy.visit(`${baseUrl}/content/${testUser2.id}/edit`);

    // Verify permissions error is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'You do not have permission to edit this content');
    cy.get('[data-testid="error-code"]').should('contain', '403');

    // Verify user is redirected or content is not editable
    cy.get('input[name="title"]').should('be.disabled');
    cy.get('textarea[name="content"]').should('be.disabled');
    cy.get('button[type="submit"]').should('be.disabled');

    // Verify error alert styling
    cy.get('[data-testid="error-message"]').should('have.class', 'error-alert');
  });

  it('should handle edge case where content ID does not exist', () => {
    // Login as user1
    cy.get('input[name="email"]').type(testUser1.email);
    cy.get('input[name="password"]').type(testUser1.password);
    cy.get('button[type="submit"]').click();
    cy.url().should('include', '/dashboard');

    // Attempt to access non-existent content
    cy.visit(`${baseUrl}/content/invalid-content-id/edit`, { failOnStatusCode: false });

    // Verify appropriate error message
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain.oneOf', [
      'Content not found',
      'This content does not exist',
      'You do not have permission to access this content'
    ]);

    // Verify user can navigate back
    cy.get('a[data-testid="back-button"]').should('be.visible').click();
    cy.url().should('include', '/dashboard');
  });

  it('should prevent direct API calls to edit another user\'s content', () => {
    // Login as user1
    cy.get('input[name="email"]').type(testUser1.email);
    cy.get('input[name="password"]').type(testUser1.password);
    cy.get('button[type="submit"]').click();
    cy.url().should('include', '/dashboard');

    // Attempt direct API call to edit user2's content
    cy.request({
      method: 'PUT',
      url: `${baseUrl}/api/content/${testUser2.id}/edit`,
      body: {
        title: 'Hacked Title',
        content: 'Hacked content'
      },
      failOnStatusCode: false
    }).then((response) => {
      // Verify 403 Forbidden response
      expect(response.status).to.equal(403);
      expect(response.body).to.have.property('error');
      expect(response.body.error).to.include('permission');
    });
  });

  it('should display permissions error with proper accessibility attributes', () => {
    // Login as user1
    cy.get('input[name="email"]').type(testUser1.email);
    cy.get('input[name="password"]').type(testUser1.password);
    cy.get('button[type="submit"]').click();
    cy.url().should('include', '/dashboard');

    // Navigate to another user's content
    cy.visit(`${baseUrl}/content/${testUser2.id}/edit`);

    // Verify error message has proper ARIA attributes
    cy.get('[data-testid="error-message"]').should('have.attr', 'role', 'alert');
    cy.get('[data-testid="error-message"]').should('have.attr', 'aria-live', 'polite');

    // Verify error message is announced to screen readers
    cy.get('[data-testid="error-message"]').invoke('text').should('not.be.empty');

    // Verify focus management
    cy.get('[data-testid="error-message"]').should('have.focus').or('be.visible');
  });

  it('should maintain session security and not expose sensitive data in error', () => {
    // Login as user1
    cy.get('input[name="email"]').type(testUser1.email);
    cy.get('input[name="password"]').type(testUser1.password);
    cy.get('button[type="submit"]').click();
    cy.url().should('include', '/dashboard');

    // Navigate to another user's content
    cy.visit(`${baseUrl}/content/${testUser2.id}/edit`);

    // Verify error message does not expose sensitive information
    cy.get('[data-testid="error-message"]').invoke('text').then((text) => {
      expect(text).to.not.include(testUser2.email);
      expect(text).to.not.include(testUser2.password);
      expect(text).to.not.include(testUser2.id);
    });

    // Verify no sensitive data in page source
    cy.get('body').invoke('html').then((html) => {
      expect(html).to.not.include(testUser2.password);
    });
  });
});
